speedrun/pt.styles:
/* speedrun page only */
.note{margin-top:14px;font-size:15px;color:var(--ink3);max-width:68ch}
.clock{max-width:68ch;color:var(--ink2)}
.cats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.cats .card p{color:var(--ink2);margin-top:8px;font-size:16px}
.chip{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--honey-ink);background:var(--honey-wash);border-radius:999px;padding:2px 10px;margin-bottom:8px}
.rules{margin:12px 0 0;padding-left:20px;color:var(--ink2);font-size:16px}
.rules li{margin:6px 0}
.rules b{color:var(--ink)}
.daily{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,380px);gap:32px;align-items:start}
.goal-label{font-size:13px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--ink3);margin-bottom:8px}
.goal{font-family:ui-monospace,"Cascadia Mono",Consolas,monospace;font-size:15px;line-height:1.5;background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:12px 14px;overflow-wrap:anywhere;color:var(--ink)}
.side p{color:var(--ink2);font-size:16px;margin-top:14px}
.files{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.files a{display:flex;flex-direction:column;gap:4px;text-decoration:none;color:var(--ink);background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px}
.files a:hover{border-color:var(--border2);background:var(--surface2)}
.files b{font-family:var(--font-display);font-size:20px;font-weight:700}
.files a>span{font-size:14px;color:var(--ink3)}
@media (max-width:820px){
  .cats,.daily{grid-template-columns:1fr}
  .files{grid-template-columns:repeat(2,minmax(0,1fr))}
}

